// Workflow kontrolü
const workflowType = $('Select Conversion Ref').first().json.workflowType;
const csvData = $input.first().json.stdout;  // ← .item yerine .first() kullan
const lines = csvData.trim().split('\n');
const headers = lines[0].split(',');

// CSV'yi objelere parse et
const parsedData = lines.slice(1).map(line => {
  const values = line.split(',');
  const obj = {};
  headers.forEach((header, index) => {
    const key = header.trim();
    obj[key] = values[index]?.trim() || '';
  });
  return obj;
});

let result;

if (workflowType === "Standard Workflow") {
  // SampleID'ye göre grupla ve reads'leri topla
  const grouped = {};

  parsedData.forEach(item => {
    const sampleId = item['SampleID'];

    if (!grouped[sampleId]) {
      // İlk kez görülen sample - kopyala
      grouped[sampleId] = { ...item };
      grouped[sampleId]['# Reads'] = parseInt(item['# Reads'].replace(/,/g, '')) || 0;
      grouped[sampleId]['Lane'] = '0';  // Lane'i 0 yap
    } else {
      // Zaten var - reads'i ekle
      grouped[sampleId]['# Reads'] += parseInt(item['# Reads'].replace(/,/g, '')) || 0;
    }
  });

  // Objeyi array'e çevir
  result = Object.values(grouped);

} else {
  // Normal workflow - olduğu gibi bırak
  result = parsedData;
}

return result.map(item => ({ json: item }));

// cat komutundan gelen stdout'u al
const inputText = $json.stdout;

// Input kontrolü
if (!inputText || typeof inputText !== 'string') {
  throw new Error('stdout bulunamadı veya string değil');
}

// [Data] bölümünü bul ve parse et
const dataSectionMatch = inputText.split('Data]');
if (dataSectionMatch.length < 2) {
  throw new Error('Sample sheet içinde [Data] section bulunamadı');
}

const dataSection = dataSectionMatch[1];

// Satırlara böl ve boş satırları temizle
const lines = dataSection.trim().split('\n').filter(line => line.trim());
if (lines.length < 2) {
  throw new Error('[Data] section\'da yeterli satır yok');
}

// İlk satır header
const headers = lines[0].split(',');

// Lane sütunu var mı kontrol et
const hasLaneColumn = headers.includes('Lane');

// Geri kalan satırlar sample verileri
const samples = [];
for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',');

  // Her satırı objeye çevir
  const sample = {};
  headers.forEach((header, index) => {
    sample[header] = values[index] || '';
  });

  // Lane sütunu yoksa ekle ve 0 değeri ata
  if (!hasLaneColumn) {
    sample['Lane'] = '0';
  }

  samples.push(sample);
}

// Output olarak döndür - her sample ayrı item
return samples.map(sample => ({ json: sample }));

// Reverse complement helper
function reverseComplement(seq) {
  const complement = { A: 'T', T: 'A', C: 'G', G: 'C' };
  return seq
    .toUpperCase()
    .split('')
    .reverse()
    .map(base => complement[base] || base)
    .join('');
}

// Hangi cihazda çalıştığını önceki node'dan al
const instrumentModel = $('Select Conversion Ref').first().json.instrumentModel || '';

const needsRC = 
  instrumentModel.includes('NextSeq 2000') || 
  instrumentModel.includes('NovaSeq X');

const items = $input.all();

return items.map(item => {
  const data = { ...item.json };

  if (needsRC && data.Index2) {
    const originalIndex2 = data.Index2;
    const rcIndex2 = reverseComplement(originalIndex2);

    data.Index2 = rcIndex2;

    // Index_set alanını da güncelle (varsa)
    if (data.Index_set && data.Index_set.includes('-')) {
      const parts = data.Index_set.split('-');
      // Index_set'teki i2 kısmı zaten RC halinde yazılmış olabilir,
      // burada Index'i sabit tutup Index2'nin RC'sini yazıyoruz
      data.Index_set = `${parts[0]}-${rcIndex2}`;
    }
  }

  return { json: data };
});

const firstItem = $('Select Conversion Ref').first().json;
const readsSettings = firstItem.readsSettings || '';

const needsTrim = readsSettings === '151-8-8-151';

const items = $input.all();

return items.map(item => {
  const data = { ...item.json };

  if (needsTrim) {
    if (data.i7_sequence && data.i7_sequence.length === 10) {
      data.i7_sequence = data.i7_sequence.slice(0, 8);
    }
    if (data.i5_sequence && data.i5_sequence.length === 10) {
      data.i5_sequence = data.i5_sequence.slice(0, 8);
    }
  }

  return { json: data };
});

// Log rows dropped because critical lookups failed.
// These rows would have produced NULL-only "shadow twin" rows in the reads table.
// Returning [] so nothing flows downstream; the structured log lives in the execution data.
const items = $input.all();
for (const it of items) {
  const j = it.json || {};
  const missing = [];
  if (j.index_ref === undefined || j.index_ref === null || j.index_ref === '') missing.push('index_ref');
  if (j.requesting_caresite_ref === undefined || j.requesting_caresite_ref === null || j.requesting_caresite_ref === '') missing.push('requesting_caresite_ref');
  if (j.performing_care_site_ref === undefined || j.performing_care_site_ref === null || j.performing_care_site_ref === '') missing.push('performing_care_site_ref');
  console.log(JSON.stringify({
    event: 'subreads.lookup_failure',
    sample_id: j.Sample_ID || j.sample_id || null,
    conversion_ref: j.conversion_ref || null,
    lane: j.Lane !== undefined ? j.Lane : (j.lane !== undefined ? j.lane : null),
    sample_project: j.Sample_Project || j.sample_project || null,
    kit_ref: j.kit_ref !== undefined ? j.kit_ref : (j.kits_ref !== undefined ? j.kits_ref : null),
    missing_fields: missing,
    index_seq_i7: j.Index || null,
    index_seq_i5: j.Index2 || null,
    requested_by: j.Requested_By || null,
    prepared_by: j.Prepared_By || null
  }));
}
return [];

// Drop rows where the same (i7, i5) sequence pair matched MULTIPLE indices entries
// (e.g. same UDP barcode under two kits). Logs structured JSON for downstream debugging.
// Returning [] so nothing flows to the upsert path.
const items = $input.all();
for (const it of items) {
  const j = it.json || {};
  console.log(JSON.stringify({
    event: 'subreads.multi_index_match',
    sample_id: j.Sample_ID || j.sample_id || null,
    conversion_ref: j.conversion_ref || null,
    lane: j.Lane !== undefined ? j.Lane : (j.lane !== undefined ? j.lane : null),
    sample_project: j.Sample_Project || j.sample_project || null,
    library_prep_kit: j.Library_Prep_Kit || null,
    index_i7: j.Index || null,
    index_i5: j.Index2 || null,
    index_match_count: j.index_match_count,
    chosen_index_ref: j.index_ref || null
  }));
}
return [];

